if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['item_name']??'');$cat=trim($_POST['category']??'');$loc=trim($_POST['location']??'');$date=$_POST['item_date']??'';$desc=trim($_POST['description']??'');if($name===''||!valid_category($cat)||$loc===''||$date===''||$desc==='')$message='Please complete all required fields.';else{$up=upload_item_image($_FILES['image']??null,__DIR__.'/uploads');if(!$up['success'])$message=$up['message'];else{$uid=(int)$_SESSION['user_id'];$img=$up['filename'];$type='lost';$status='active';$s=mysqli_prepare($conn,'INSERT INTO items(user_id,item_name,category,description,location,item_date,image,type,status) VALUES(?,?,?,?,?,?,?,?,?)');mysqli_stmt_bind_param($s,'issssssss',$uid,$name,$cat,$desc,$loc,$date,$img,$type,$status);if(mysqli_stmt_execute($s)){set_flash('success','Lost item reported successfully.');header('Location: my-reports.php');exit();}delete_item_image($img,__DIR__.'/uploads');$message='Could not save the report.';}}}
